const loaded = new Map<string, Art>();

/** The artwork for a sticker, or undefined if curation has dropped it. */
export function stickerArt(id: string): Art | undefined {
  const load = ART[id];
  if (!load) return undefined;

  let art = loaded.get(id);
  if (!art) {
    art = load();
    loaded.set(id, art);
  }
  return art;
}
